import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { organizationLogic } from 'scenes/organizationLogic'

import { rolesList } from 'products/platform_features/frontend/generated/api'
import type { RoleApi } from 'products/platform_features/frontend/generated/api.schemas'

const ROLES_PAGE_SIZE = 200

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mentionRolesLogicValues {
    currentOrganizationId: string // organizationLogic
    roles: RoleApi[]
    rolesLoaded: boolean
    rolesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mentionRolesLogicActions {
    ensureRolesLoaded: () => {
        value: true
    }
    loadRoles: () => any
    loadRolesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadRolesSuccess: (
        roles: RoleApi[],
        payload?: any
    ) => {
        roles: RoleApi[]
        payload?: any
    }
}

export type mentionRolesLogicType = MakeLogicType<mentionRolesLogicValues, mentionRolesLogicActions>

/** The organization's roles, for role @mentions and role chips. */
export const mentionRolesLogic = kea<mentionRolesLogicType>([
    path(['lib', 'components', 'RichContentEditor', 'mentionRolesLogic']),
    connect(() => ({ values: [organizationLogic, ['currentOrganizationId']] })),
    actions({
        // Loads roles unless they already loaded or a load is in flight. A failed load leaves roles
        // unloaded, so the next caller retries it.
        ensureRolesLoaded: true,
    }),
    loaders(({ values }) => ({
        roles: [
            [] as RoleApi[],
            {
                loadRoles: async () => {
                    const roles: RoleApi[] = []
                    for (let offset = 0; ; offset += ROLES_PAGE_SIZE) {
                        const page = await rolesList(values.currentOrganizationId, { limit: ROLES_PAGE_SIZE, offset })
                        roles.push(...page.results)
                        if (!page.next) {
                            return roles
                        }
                    }
                },
            },
        ],
    })),
    reducers({
        rolesLoaded: [false, { loadRolesSuccess: () => true }],
    }),
    listeners(({ actions, values }) => ({
        ensureRolesLoaded: () => {
            if (!values.rolesLoaded && !values.rolesLoading) {
                actions.loadRoles()
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.ensureRolesLoaded()
    }),
])
